import{_ as i,o as a,c as n,ai as h}from"./chunks/framework.BxxKhjs3.js";const E=JSON.parse('{"title":"35-match 表达式","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/35-match 表达式/35-match 表达式.md","filePath":"仓颉入门到实战/35-match 表达式/35-match 表达式.md","lastUpdated":1736065340000,"__rawMarkdown":"# 35-match 表达式\\n\\n仓颉支持两种 `match` 表达式，第一种是包含待匹配值的 `match` 表达式，第二种是不含待匹配值的 `match` 表达式。\\n\\n## 含匹配值的 match 表达式\\n\\n```javascript\\nmain() {\\n    let x = 0\\n    match (x) {\\n        case 1 => let r1 = \\"x = 1\\"\\n                  print(r1)\\n        case 0 => let r2 = \\"x = 0\\" // Matched.\\n                  print(r2)\\n        case _ => let r3 = \\"x != 1 and x != 0\\"\\n                  print(r3)\\n    }\\n}\\n```\\n\\n`match` 表达式要求所有匹配必须是穷尽（exhaustive）的，意味着待匹配表达式的所有可能取值都应该被考虑到。当 `match` 表达\\n\\n式非穷尽，或者编译器判断不出是否穷尽时，均会编译报错\\n\\n### pattern guard\\n\\n在 `case` 分支的模式之后，可以使用 `pattern guard` 进一步对匹配出来的结果进行判断。`pattern guard` 使用 `where cond` 表示，要求表达式 `cond` 的类型为 `Bool`。\\n\\n```javascript\\nenum RGBColor {\\n    | Red(Int16) | Green(Int16) | Blue(Int16)\\n}\\nmain() {\\n    let c = RGBColor.Green(-100)\\n    let cs = match (c) {\\n        case Red(r) where r < 0 => \\"Red = 0\\"\\n        case Red(r) => \\"Red = ${r}\\"\\n        case Green(g) where g < 0 => \\"Green = 0\\" // Matched.\\n        case Green(g) => \\"Green = ${g}\\"\\n        case Blue(b) where b < 0 => \\"Blue = 0\\"\\n        case Blue(b) => \\"Blue = ${b}\\"\\n    }\\n    print(cs)\\n}\\n```\\n\\n\\n\\n\\n\\n## 没有匹配值的 match 表达式\\n\\n与包含待匹配值的 `match` 表达式相比，关键字 `match` 之后并没有待匹配的表达式，并且 `case` 之后不再是 `pattern`，而是类\\n\\n型为 `Bool` 的表达式\\n\\n```javascript\\nmain() {\\n    let x = -1\\n    match {\\n        case x > 0 => print(\\"x > 0\\")\\n        case x < 0 => print(\\"x < 0\\") // Matched.\\n        case _ => print(\\"x = 0\\")\\n    }\\n}\\n\\n```\\n\\n## match 表达式的类型\\n\\n对于 `match` 表达式（无论是否有匹配值），\\n\\n- 在上下文有明确的类型要求时，要求每个 `case` 分支中 `=>` 之后的代码块的类型是上下文所要求的类型的子类型；\\n- 在上下文没有明确的类型要求时，`match` 表达式的类型是每个 `case` 分支中 `=>` 之后的代码块的类型的最小公共父类型；\\n- 当 `match` 表达式的值没有被使用时，其类型为 `Unit`，不要求各分支的类型有最小公共父类型。\\n\\n下面分别举例说明。\\n\\n```javascript\\nlet x = 2\\nlet s: String = match (x) {\\n    case 0 => \\"x = 0\\"\\n    case 1 => \\"x = 1\\"\\n    case _ => \\"x != 0 and x != 1\\" // Matched.\\n}\\n```\\n\\n上面的例子中，定义变量 `s` 时，显式地标注了其类型为 `String`，属于上下文类型信息明确的情况，因此要求每个 `case` 的 `=>` 之后的代码块的类型均是 `String` 的子类型，显然上例中 `=>` 之后的字符串类型的字面量均满足要求。\\n\\n再来看一个没有上下文类型信息的例子：\\n\\n```javascript\\nlet x = 2\\nlet s = match (x) {\\n    case 0 => \\"x = 0\\"\\n    case 1 => \\"x = 1\\"\\n    case _ => \\"x != 0 and x != 1\\" // Matched.\\n}\\n```\\n\\n上例中，定义变量 `s` 时，未显式标注其类型，因为每个 `case` 的 `=>` 之后的代码块的类型均是 `String`，所以 `match` 表达式的类型是 `String`，进而可确定 `s` 的类型也是 `String`。"}'),t={name:"仓颉入门到实战/35-match 表达式/35-match 表达式.md"};function e(l,s,p,k,r,d){return a(),n("div",null,[...s[0]||(s[0]=[h("",22)])])}const g=i(t,[["render",e]]);export{E as __pageData,g as default};
